//! Oracle rows and real document/packet/scene builders for the contour producer join (L07-F).
//!
//! `fixtures/object-scene-producer-contour/oracle.txt` was generated by `tools/gen_oracle.js`
//! from baseline fbe4b8a3: the verbatim layer-level and element-level Order blocks of
//! `buildSceneJson` (src/js/engine-bridge.js) run in a Node `vm` over 120 scenes, with a
//! hidden layer kept in its slot as `{ items: [] }` exactly as the baseline layer loop does.
//! Row format: `P id spec expected natural compact storage`; `spec` is `;`-joined
//! `rank:ords[!]` (`-` undefined, `=` no shapes, `!` hidden layer), the other columns are
//! `layer.element` labels back to front (`-` = nothing painted).
//!
//! Each scene becomes a real v2 native document (layers, objects and plan elements stored
//! reversed, so array positions never equal paint order), a real `ObjectFramePacket`, a real
//! `ObjectRenderScene` and a real `ObjectPaintPlan` whose command order is read back.

use crate::object_codec::{decode_project, decode_storage_project};
use crate::object_document::FrameScopeKind;
use crate::object_frame_packet::{prepare_object_frame, ObjectFramePacket, ObjectFrameSelector};
use crate::object_render_scene::{
    paint_test_document, prepare_object_paint_plan, prepare_object_render_scene, ObjectRenderScene,
};
use crate::revision::ObjectSnapshot;
use serde_json::{json, Value};

pub(crate) const ORACLE: &str = include_str!("fixtures/object-scene-producer-contour/oracle.txt");
pub(crate) const FRAME: u32 = 7;
pub(crate) const STROKE_IDS: [&str; 4] = ["a", "b", "c", "d"];

pub(crate) struct LayerSpec {
    pub(crate) rank: Option<f64>,
    pub(crate) ords: Vec<Option<f64>>,
    pub(crate) hidden: bool,
}

pub(crate) struct Case {
    pub(crate) id: String,
    pub(crate) layers: Vec<LayerSpec>,
    pub(crate) expected: Vec<String>,
    pub(crate) natural: Vec<String>,
    pub(crate) compact: Vec<String>,
    pub(crate) storage: Vec<String>,
}

fn token(tok: &str) -> Option<f64> {
    (tok != "-").then(|| tok.parse::<f64>().expect("number token"))
}

fn labels_of(column: &str) -> Vec<String> {
    if column == "-" {
        Vec::new()
    } else {
        column.split(',').map(str::to_owned).collect()
    }
}

pub(crate) fn cases() -> Vec<Case> {
    ORACLE
        .lines()
        .filter(|line| line.starts_with("P "))
        .map(|line| {
            let cols: Vec<&str> = line.split(' ').collect();
            assert_eq!(cols.len(), 7, "{line}");
            let layers = cols[2]
                .split(';')
                .map(|layer| {
                    let (body, hidden) = match layer.strip_suffix('!') {
                        Some(body) => (body, true),
                        None => (layer, false),
                    };
                    let (rank, ords) = body.split_once(':').expect("rank:ords");
                    LayerSpec {
                        rank: token(rank),
                        ords: if ords == "=" {
                            Vec::new()
                        } else {
                            ords.split(',').map(token).collect()
                        },
                        hidden,
                    }
                })
                .collect();
            Case {
                id: cols[1].to_owned(),
                layers,
                expected: labels_of(cols[3]),
                natural: labels_of(cols[4]),
                compact: labels_of(cols[5]),
                storage: labels_of(cols[6]),
            }
        })
        .collect()
}

fn order_json(value: Option<f64>) -> Value {
    match value {
        Some(number) => json!({ "static": [number] }),
        None => json!({}),
    }
}

/// Layers `L{j}` and elements `a..d`; document layers, objects and plan elements are
/// stored reversed. Every record is the admitted triangle with a distinct `fill.r`.
pub(crate) fn document(case: &Case) -> Value {
    let template = paint_test_document(&[FRAME])["objects"][0].clone();
    let mut objects = Vec::new();
    let mut elements = Vec::new();
    let mut gid = 0;
    for (j, layer) in case.layers.iter().enumerate() {
        for (k, ord) in layer.ords.iter().enumerate() {
            let uid = format!("L{j}");
            let mut record = template.clone();
            record["target"] = json!({"contextId":"scene-root","frameScope":{"kind":"authored","frame":FRAME},
                "layerUid":uid,"strokeId":STROKE_IDS[k]});
            record["fill"] =
                json!({"kind":"solid","r":(gid as f64 + 1.0) / 100.0,"g":0.4,"b":0.6,"a":0.75});
            objects.push(record);
            elements.push(json!({"layerUid":uid,"strokeId":STROKE_IDS[k],"naturalPosition":k,"order":order_json(*ord)}));
            gid += 1;
        }
    }
    objects.reverse();
    elements.reverse();
    let layers: Vec<Value> = case
        .layers
        .iter()
        .enumerate()
        .rev()
        .map(|(j, layer)| {
            let mut value = json!({ "layerUid": format!("L{j}") });
            if layer.hidden {
                value["visible"] = json!(false);
            }
            value
        })
        .collect();
    let plan_layers: Vec<Value> = case
        .layers
        .iter()
        .enumerate()
        .map(|(j, layer)| json!({"layerUid":format!("L{j}"),"naturalPosition":j,"order":order_json(layer.rank)}))
        .collect();
    json!({"format":"nemo.native-object-document","formatVersion":2,"totalFrames":21,
        "layers":layers,"objects":objects,
        "compositionOrder":{"format":"nemo.native-object-order-plan","formatVersion":1,"documentFormatVersion":2,
        "contexts":[{"contextId":"scene-root","layers":plan_layers,
        "scopes":[{"frameScope":{"kind":"authored","frame":FRAME},"elements":elements}]}],
        "migration":"explicit-plan-required","referencePolicy":"unresolved"}})
}

pub(crate) fn snapshot(value: &Value, instance: &str) -> ObjectSnapshot {
    ObjectSnapshot::new(
        instance,
        decode_storage_project(&serde_json::to_vec(value).unwrap()).unwrap(),
    )
    .unwrap()
}

pub(crate) fn packet_of(
    snapshot: &ObjectSnapshot,
    kind: FrameScopeKind,
    frame: u32,
) -> ObjectFramePacket {
    prepare_object_frame(
        snapshot,
        &ObjectFrameSelector {
            instance_id: snapshot.instance_id(),
            document_id: snapshot.document_id(),
            content_revision: snapshot.content_revision(),
            document_snapshot_id: snapshot.snapshot_id(),
            context_id: "scene-root",
            scope_kind: kind,
            frame,
        },
    )
    .unwrap()
}

pub(crate) fn packet(snapshot: &ObjectSnapshot) -> ObjectFramePacket {
    packet_of(snapshot, FrameScopeKind::Authored, FRAME)
}

pub(crate) fn selector(packet: &ObjectFramePacket) -> ObjectFrameSelector<'_> {
    ObjectFrameSelector {
        instance_id: packet.instance_id(),
        document_id: packet.document_id(),
        content_revision: packet.content_revision(),
        document_snapshot_id: packet.document_snapshot_id(),
        context_id: packet.context_id(),
        scope_kind: packet.scope_kind().clone(),
        frame: packet.frame(),
    }
}

pub(crate) fn scene(packet: &ObjectFramePacket) -> ObjectRenderScene {
    prepare_object_render_scene(packet, &selector(packet)).unwrap()
}

/// Scene builder with the signature the existing paint-plan case runners expect.
pub(crate) fn paint_scene(value: &Value, frame: u32) -> ObjectRenderScene {
    let snapshot = snapshot(value, "paint-test");
    scene(&packet_of(&snapshot, FrameScopeKind::Authored, frame))
}

/// A v1 (no numeric order plan) Reference-scope scene: its paint plan is unavailable.
pub(crate) fn reference_scene() -> ObjectRenderScene {
    let cases: Value = serde_json::from_str(include_str!(
        "../../engineering/application/examples/native-object-v1/cases.json"
    ))
    .unwrap();
    let source = json!({"format":"nemo.native-object-document","formatVersion":1,"totalFrames":21,
        "layers":[{"layerUid":"legacy layer:alpha"},{"layerUid":"0"}],"objects":cases["records"]});
    let snapshot = ObjectSnapshot::new(
        "contour-instance",
        decode_project(&serde_json::to_vec(&source).unwrap()).unwrap(),
    )
    .unwrap();
    scene(&packet_of(&snapshot, FrameScopeKind::Reference, 12))
}

/// `layer.element` of a command's target, e.g. `("L2", "b")` -> `2.1`.
pub(crate) fn label_of(layer_uid: &str, stroke_id: &str) -> String {
    format!("{}.{}", &layer_uid[1..], stroke_id.as_bytes()[0] - b'a')
}

/// Command order of the real paint plan built from the case.
pub(crate) fn plan_labels(case: &Case) -> Vec<String> {
    let snap = snapshot(&document(case), "contour-plan");
    let pk = packet(&snap);
    let scene = scene(&pk);
    let plan = prepare_object_paint_plan(&scene, &selector(scene.packet())).unwrap();
    plan.commands()
        .map(|command| {
            let target = command.source().record().target();
            label_of(target.layer_uid(), target.stroke_id())
        })
        .collect()
}

/// Ids of the rows whose real plan order differs from the chosen oracle column.
pub(crate) fn divergences(cases: &[Case], column: fn(&Case) -> &Vec<String>) -> Vec<String> {
    cases
        .iter()
        .filter(|case| &plan_labels(case) != column(case))
        .map(|case| case.id.clone())
        .collect()
}
